    'docs.conn.infra.p': { en: `Your deployments and your infrastructure-as-code configuration.`, de: `Ihre Deployments und Ihre Infrastructure-as-Code-Konfiguration.`, es: `Sus despliegues y su configuración de infraestructura como código.`, it: `I tuoi deployment e la tua configurazione infrastructure-as-code.`, nl: `Uw deployments en uw infrastructure-as-code-configuratie.`, pt: `Os seus deployments e a sua configuração de infraestrutura como código.` },
    'docs.conn.infra.tools': { en: `Kubernetes, Terraform`, de: `Kubernetes, Terraform`, es: `Kubernetes, Terraform`, it: `Kubernetes, Terraform`, nl: `Kubernetes, Terraform`, pt: `Kubernetes, Terraform` },
    'docs.conn.intro': { en: `This list reflects the categories of tools LEKA can connect to one another. Exact availability for your stack depends on your environment: talk to the team about it.`, de: `Diese Liste zeigt die Kategorien von Tools, die LEKA miteinander verbinden kann. Die genaue Verfügbarkeit für Ihren Stack hängt von Ihrer Umgebung ab: Sprechen Sie mit dem Team darüber.`, es: `Esta lista refleja las categorías de herramientas que LEKA puede conectar entre sí. La disponibilidad exacta para su stack depende de su entorno: hable de ello con el equipo.`, it: `Questo elenco riflette le categorie di strumenti che LEKA può collegare tra loro. La disponibilità esatta per il tuo stack dipende dal tuo ambiente: parlane con il team.`, nl: `Deze lijst weerspiegelt de categorieën tools die LEKA met elkaar kan verbinden. De exacte beschikbaarheid voor uw stack hangt af van uw omgeving: bespreek dit met het team.`, pt: `Esta lista reflete as categorias de ferramentas que a LEKA consegue ligar entre si. A disponibilidade exata para a sua stack depende do seu ambiente: fale sobre isso com a equipa.` },
    'docs.conn.meta_title': { en: `Connectors, LEKA`, de: `Konnektoren, LEKA`, es: `Conectores, LEKA`, it: `Connettori, LEKA`, nl: `Connectoren, LEKA`, pt: `Conectores, LEKA` },
    'docs.conn.obs.h': { en: `Monitoring`, de: `Monitoring`, es: `Supervisión`, it: `Monitoraggio`, nl: `Monitoring`, pt: `Monitorização` },
    'docs.conn.obs.p': { en: `Your real-time metrics and alerts, to link a signal to its likely cause.`, de: `Ihre Echtzeit-Metriken und Alarme, um ein Signal mit seiner wahrscheinlichen Ursache zu verknüpfen.`, es: `Sus métricas y alertas en tiempo real, para vincular una señal con su causa probable.`, it: `Le tue metriche e i tuoi avvisi in tempo reale, per collegare un segnale alla sua causa probabile.`, nl: `Uw real-time statistieken en meldingen, om een signaal te koppelen aan de waarschijnlijke oorzaak ervan.`, pt: `As suas métricas e alertas em tempo real, para ligar um sinal à sua causa provável.` },
    'docs.conn.obs.tools': { en: `Datadog, Sentry`, de: `Datadog, Sentry`, es: `Datadog, Sentry`, it: `Datadog, Sentry`, nl: `Datadog, Sentry`, pt: `Datadog, Sentry` },
    'docs.conn.outro': { en: `A tool you use isn't listed here? <a class="link" style="display:inline-flex" href="./demo.html?type=team">Write to us, we'll get back to you directly.</a>`, de: `Ein von Ihnen genutztes Tool ist hier nicht aufgeführt? <a class="link" style="display:inline-flex" href="./demo.html?type=team">Schreiben Sie uns, wir melden uns direkt bei Ihnen.</a>`, es: `¿Una herramienta que utiliza no aparece aquí? <a class="link" style="display:inline-flex" href="./demo.html?type=team">Escríbanos, le responderemos directamente.</a>`, it: `Uno strumento che usi non è elencato qui? <a class="link" style="display:inline-flex" href="./demo.html?type=team">Scrivici, ti risponderemo direttamente.</a>`, nl: `Staat een tool die u gebruikt hier niet bij? <a class="link" style="display:inline-flex" href="./demo.html?type=team">Schrijf ons, we reageren rechtstreeks.</a>`, pt: `Uma ferramenta que utiliza não está aqui listada? <a class="link" style="display:inline-flex" href="./demo.html?type=team">Escreva-nos, responderemos diretamente.</a>` },
    'docs.conn.tickets.h': { en: `Tickets`, de: `Tickets`, es: `Tickets`, it: `Ticket`, nl: `Tickets`, pt: `Tickets` },
    'docs.conn.tickets.p': { en: `Open incidents, requests and tickets, to place an intent within what's already happening in your business.`, de: `Offene Vorfälle, Anfragen und Tickets, um eine Absicht in das einzuordnen, was in Ihrem Unternehmen bereits geschieht.`, es: `Incidentes, solicitudes y tickets abiertos, para situar una intención dentro de lo que ya está ocurriendo en su empresa.`, it: `Incidenti, richieste e ticket aperti, per collocare un intento in ciò che sta già accadendo nella tua azienda.`, nl: `Openstaande incidenten, verzoeken en tickets, om een intentie te plaatsen binnen wat er al gebeurt in uw bedrijf.`, pt: `Incidentes, pedidos e tickets abertos, para situar uma intenção dentro do que já está a acontecer na sua empresa.` },
    'docs.conn.tickets.tools': { en: `Jira, ServiceNow`, de: `Jira, ServiceNow`, es: `Jira, ServiceNow`, it: `Jira, ServiceNow`, nl: `Jira, ServiceNow`, pt: `Jira, ServiceNow` },
    'docs.conn.title': { en: `The integrations LEKA understands`, de: `Die Integrationen, die LEKA versteht`, es: `Las integraciones que LEKA comprende`, it: `Le integrazioni che LEKA comprende`, nl: `De integraties die LEKA begrijpt`, pt: `As integrações que a LEKA compreende` },
