    'home.case.t5h': { en: `Actions proposed`, de: `Vorgeschlagene Maßnahmen`, es: `Acciones propuestas`, it: `Azioni proposte`, nl: `Voorgestelde acties`, pt: `Ações propostas` },
    'home.case.t5p': { en: `Fix, rollback, or configuration adjustment`, de: `Fix, Rollback oder Konfigurationsanpassung`, es: `Corrección, reversión o ajuste de configuración`, it: `Correzione, rollback o modifica della configurazione`, nl: `Fix, rollback of configuratieaanpassing`, pt: `Correção, rollback ou ajuste de configuração` },
    'home.case.t6h': { en: `Ready for decision`, de: `Bereit für die Entscheidung`, es: `Listo para decidir`, it: `Pronto per la decisione`, nl: `Klaar voor beslissing`, pt: `Pronto para decisão` },
    'home.case.t6p': { en: `Human validation required before execution`, de: `Menschliche Freigabe vor der Ausführung erforderlich`, es: `Se requiere validación humana antes de la ejecución`, it: `È richiesta la convalida umana prima dell'esecuzione`, nl: `Menselijke goedkeuring vereist vóór uitvoering`, pt: `É necessária validação humana antes da execução` },
    'home.case.title': { en: `From a problem to a solution.`, de: `Von einem Problem zu einer Lösung.`, es: `De un problema a una solución.`, it: `Da un problema a una soluzione.`, nl: `Van een probleem naar een oplossing.`, pt: `De um problema a uma solução.` },
    'home.closing.body': { en: `You keep the intent, the judgement and the decision. LEKA takes on the understanding and the execution within your business's context.`, de: `Sie behalten die Absicht, das Urteilsvermögen und die Entscheidung. LEKA übernimmt das Verständnis und die Ausführung im Kontext Ihres Unternehmens.`, es: `Usted conserva la intención, el juicio y la decisión. LEKA se encarga de la comprensión y la ejecución en el contexto de su empresa.`, it: `Tu mantieni l'intento, il giudizio e la decisione. LEKA si occupa della comprensione e dell'esecuzione nel contesto della tua azienda.`, nl: `U behoudt de intentie, het oordeel en de beslissing. LEKA neemt het begrip en de uitvoering op zich binnen de context van uw bedrijf.`, pt: `Você mantém a intenção, o julgamento e a decisão. A LEKA assume a compreensão e a execução no contexto da sua empresa.` },
    'home.closing.p1h': { en: `A well-understood business`, de: `Ein gut verstandenes Unternehmen`, es: `Una empresa bien comprendida`, it: `Un'azienda ben compresa`, nl: `Een goed begrepen bedrijf`, pt: `Uma empresa bem compreendida` },
    'home.closing.p1p': { en: `Without manual mapping.`, de: `Ohne manuelle Kartierung.`, es: `Sin mapeo manual.`, it: `Senza mappatura manuale.`, nl: `Zonder handmatige mapping.`, pt: `Sem mapeamento manual.` },
    'home.closing.p2h': { en: `Faster decisions`, de: `Schnellere Entscheidungen`, es: `Decisiones más rápidas`, it: `Decisioni più rapide`, nl: `Snellere beslissingen`, pt: `Decisões mais rápidas` },
    'home.closing.p2p': { en: `Context arrives with the question.`, de: `Der Kontext kommt mit der Frage.`, es: `El contexto llega con la pregunta.`, it: `Il contesto arriva insieme alla domanda.`, nl: `Context komt mee met de vraag.`, pt: `O contexto chega com a pergunta.` },
    'home.closing.p3h': { en: `Autonomous teams`, de: `Autonome Teams`, es: `Equipos autónomos`, it: `Team autonomi`, nl: `Autonome teams`, pt: `Equipas autónomas` },
    'home.closing.p3p': { en: `Knowledge stops being a bottleneck.`, de: `Wissen ist kein Engpass mehr.`, es: `El conocimiento deja de ser un cuello de botella.`, it: `La conoscenza smette di essere un collo di bottiglia.`, nl: `Kennis is geen knelpunt meer.`, pt: `O conhecimento deixa de ser um estrangulamento.` },
    'home.closing.p4h': { en: `A system that improves`, de: `Ein System, das sich verbessert`, es: `Un sistema que mejora`, it: `Un sistema che migliora`, nl: `Een systeem dat verbetert`, pt: `Um sistema que melhora` },
    'home.closing.p4p': { en: `Every change enriches it.`, de: `Jede Änderung bereichert es.`, es: `Cada cambio lo enriquece.`, it: `Ogni cambiamento lo arricchisce.`, nl: `Elke wijziging verrijkt het.`, pt: `Cada mudança enriquece-o.` },
    'home.closing.title': { en: `Complexity doesn't disappear.<br><span>It changes hands.</span>`, de: `Komplexität verschwindet nicht.<br><span>Sie wechselt die Hände.</span>`, es: `La complejidad no desaparece.<br><span>Cambia de manos.</span>`, it: `La complessità non scompare.<br><span>Cambia di mano.</span>`, nl: `Complexiteit verdwijnt niet.<br><span>Ze verandert van eigenaar.</span>`, pt: `A complexidade não desaparece.<br><span>Muda de mãos.</span>` },
    'home.hero.cta_secondary': { en: `See how it works`, de: `So funktioniert es`, es: `Ver cómo funciona`, it: `Scopri come funziona`, nl: `Bekijk hoe het werkt`, pt: `Ver como funciona` },
    'home.hero.eyebrow': { en: `Your business's technological nervous system`, de: `Das technologische Nervensystem Ihres Unternehmens`, es: `El sistema nervioso tecnológico de su empresa`, it: `Il sistema nervoso tecnologico della tua azienda`, nl: `Het technologische zenuwstelsel van uw bedrijf`, pt: `O sistema nervoso tecnológico da sua empresa` },
    'home.hero.lead': { en: `LEKA connects your tools, your data and your documentation to build a living understanding of your business and answer every intent in its real context.`, de: `LEKA verbindet Ihre Tools, Ihre Daten und Ihre Dokumentation zu einem lebendigen Verständnis Ihres Unternehmens und beantwortet jede Absicht in ihrem echten Kontext.`, es: `LEKA conecta sus herramientas, sus datos y su documentación para construir una comprensión viva de su empresa y responder a cada intención en su contexto real.`, it: `LEKA collega i tuoi strumenti, i tuoi dati e la tua documentazione per costruire una comprensione viva della tua azienda e rispondere a ogni intento nel suo contesto reale.`, nl: `LEKA verbindt uw tools, uw data en uw documentatie tot een levend begrip van uw bedrijf en beantwoordt elke intentie in de juiste context.`, pt: `A LEKA liga as suas ferramentas, os seus dados e a sua documentação para construir uma compreensão viva da sua empresa e responder a cada intenção no seu contexto real.` },
    'home.hero.statement': { en: `You decide. LEKA carries the complexity.`, de: `Sie entscheiden. LEKA trägt die Komplexität.`, es: `Usted decide. LEKA se encarga de la complejidad.`, it: `Tu decidi. LEKA si occupa della complessità.`, nl: `U beslist. LEKA draagt de complexiteit.`, pt: `Você decide. A LEKA carrega a complexidade.` },
    'home.hero.title': { en: `You know<br>what you want.<br><em>LEKA knows how.</em>`, de: `Sie wissen,<br>was Sie wollen.<br><em>LEKA weiß, wie.</em>`, es: `Usted sabe<br>lo que quiere.<br><em>LEKA sabe cómo.</em>`, it: `Tu sai<br>cosa vuoi.<br><em>LEKA sa come.</em>`, nl: `U weet<br>wat u wilt.<br><em>LEKA weet hoe.</em>`, pt: `Você sabe<br>o que quer.<br><em>A LEKA sabe como.</em>` },
    'home.living.body': { en: `Every change in your business feeds LEKA's understanding. The next requests are handled with the most recent context, not the one from six months ago.`, de: `Jede Veränderung in Ihrem Unternehmen fließt in das Verständnis von LEKA ein. Die nächsten Anfragen werden mit dem aktuellsten Kontext bearbeitet, nicht mit dem von vor sechs Monaten.`, es: `Cada cambio en su empresa alimenta la comprensión de LEKA. Las próximas solicitudes se tratan con el contexto más reciente, no con el de hace seis meses.`, it: `Ogni cambiamento nella tua azienda alimenta la comprensione di LEKA. Le prossime richieste vengono gestite con il contesto più recente, non quello di sei mesi fa.`, nl: `Elke verandering in uw bedrijf voedt het begrip van LEKA. De volgende verzoeken worden behandeld met de meest recente context, niet die van zes maanden geleden.`, pt: `Cada mudança na sua empresa alimenta a compreensão da LEKA. Os próximos pedidos são tratados com o contexto mais recente, não o de há seis meses.` },
    'home.living.c1h': { en: `Your business today`, de: `Ihr Unternehmen heute`, es: `Su empresa hoy`, it: `La tua azienda oggi`, nl: `Uw bedrijf vandaag`, pt: `A sua empresa hoje` },
