    'home.living.c2h': { en: `A change occurs`, de: `Eine Änderung tritt ein`, es: `Ocurre un cambio`, it: `Avviene un cambiamento`, nl: `Er treedt een wijziging op`, pt: `Ocorre uma mudança` },
    'home.living.c2li1': { en: `LEKA updates its understanding`, de: `LEKA aktualisiert sein Verständnis`, es: `LEKA actualiza su comprensión`, it: `LEKA aggiorna la sua comprensione`, nl: `LEKA werkt zijn begrip bij`, pt: `A LEKA atualiza a sua compreensão` },
    'home.living.c2li2': { en: `Links get re-adjusted`, de: `Verknüpfungen werden neu justiert`, es: `Los vínculos se reajustan`, it: `I collegamenti vengono riadattati`, nl: `Verbanden worden herzien`, pt: `As ligações são reajustadas` },
