    'home.platform.orb2': { en: `Continuously updated.`, de: `Kontinuierlich aktualisiert.`, es: `Actualizado continuamente.`, it: `Aggiornato continuamente.`, nl: `Voortdurend bijgewerkt.`, pt: `Atualizado continuamente.` },
    'home.platform.title': { en: `All your technology.<br>One single understanding.`, de: `Ihre gesamte Technologie.<br>Ein einziges Verständnis.`, es: `Toda su tecnología.<br>Una sola comprensión.`, it: `Tutta la tua tecnologia.<br>Un'unica comprensione.`, nl: `Al uw technologie.<br>Eén enkel begrip.`, pt: `Toda a sua tecnologia.<br>Uma única compreensão.` },
    'home.security.badge3': { en: `GDPR compliant`, de: `DSGVO-konform`, es: `Conforme al RGPD`, it: `Conforme al GDPR`, nl: `AVG-conform`, pt: `Conforme ao RGPD` },
    'home.security.badge5': { en: `AES-256 encryption`, de: `AES-256-Verschlüsselung`, es: `Cifrado AES-256`, it: `Crittografia AES-256`, nl: `AES-256-versleuteling`, pt: `Encriptação AES-256` },
    'home.security.body': { en: `LEKA works with your business's most sensitive knowledge. The security framework is therefore set before the first connection, not after.`, de: `LEKA arbeitet mit den sensibelsten Kenntnissen Ihres Unternehmens. Der Sicherheitsrahmen wird daher vor der ersten Verbindung festgelegt, nicht danach.`, es: `LEKA trabaja con el conocimiento más sensible de su empresa. Por ello, el marco de seguridad se define antes de la primera conexión, no después.`, it: `LEKA lavora con le conoscenze più sensibili della tua azienda. Il quadro di sicurezza viene quindi definito prima della prima connessione, non dopo.`, nl: `LEKA werkt met de meest gevoelige kennis van uw bedrijf. Het beveiligingskader wordt daarom vóór de eerste verbinding vastgesteld, niet erna.`, pt: `A LEKA trabalha com o conhecimento mais sensível da sua empresa. O quadro de segurança é, por isso, definido antes da primeira ligação, não depois.` },
    'home.security.eyebrow': { en: `Security and governance`, de: `Sicherheit und Governance`, es: `Seguridad y gobernanza`, it: `Sicurezza e governance`, nl: `Beveiliging en governance`, pt: `Segurança e governação` },
    'home.security.g1h': { en: `Hosting, your choice`, de: `Hosting nach Wahl`, es: `Alojamiento a su elección`, it: `Hosting a tua scelta`, nl: `Hosting, uw keuze`, pt: `Alojamento à sua escolha` },
    'home.security.g1p': { en: `Dedicated cloud in Europe, or deployment inside your own environment.`, de: `Dedizierte Cloud in Europa oder Bereitstellung in Ihrer eigenen Umgebung.`, es: `Nube dedicada en Europa, o despliegue dentro de su propio entorno.`, it: `Cloud dedicato in Europa, oppure distribuzione nel tuo stesso ambiente.`, nl: `Toegewijde cloud in Europa, of implementatie binnen uw eigen omgeving.`, pt: `Cloud dedicada na Europa, ou implementação no seu próprio ambiente.` },
    'home.security.g2h': { en: `No training on your data`, de: `Kein Training mit Ihren Daten`, es: `Sin entrenamiento con sus datos`, it: `Nessun addestramento sui tuoi dati`, nl: `Geen training op uw data`, pt: `Sem treino com os seus dados` },
    'home.security.g2p': { en: `Your content is never used to train a model, ours or anyone else's.`, de: `Ihre Inhalte werden niemals zum Trainieren eines Modells verwendet, weder unseres noch das eines anderen.`, es: `Su contenido nunca se utiliza para entrenar un modelo, ni el nuestro ni el de terceros.`, it: `I tuoi contenuti non vengono mai usati per addestrare un modello, né il nostro né quello di terzi.`, nl: `Uw content wordt nooit gebruikt om een model te trainen, het onze noch dat van anderen.`, pt: `O seu conteúdo nunca é usado para treinar um modelo, nem o nosso nem o de terceiros.` },
    'home.security.g3h': { en: `Your permissions are what count`, de: `Ihre Berechtigungen zählen`, es: `Sus permisos son los que cuentan`, it: `I tuoi permessi sono ciò che conta`, nl: `Uw rechten zijn bepalend`, pt: `As suas permissões é que contam` },
    'home.security.g3p': { en: `LEKA inherits your tools' access rights. No one sees what they weren't allowed to see.`, de: `LEKA übernimmt die Zugriffsrechte Ihrer Tools. Niemand sieht, was er nicht sehen durfte.`, es: `LEKA hereda los derechos de acceso de sus herramientas. Nadie ve lo que no estaba autorizado a ver.`, it: `LEKA eredita i diritti di accesso dei tuoi strumenti. Nessuno vede ciò che non era autorizzato a vedere.`, nl: `LEKA erft de toegangsrechten van uw tools. Niemand ziet wat hij niet mocht zien.`, pt: `A LEKA herda os direitos de acesso das suas ferramentas. Ninguém vê o que não estava autorizado a ver.` },
    'home.security.g4h': { en: `Full traceability`, de: `Vollständige Rückverfolgbarkeit`, es: `Trazabilidad completa`, it: `Tracciabilità completa`, nl: `Volledige traceerbaarheid`, pt: `Rastreabilidade total` },
    'home.security.g4p': { en: `Every answer cites its sources, every executed action is logged.`, de: `Jede Antwort nennt ihre Quellen, jede ausgeführte Aktion wird protokolliert.`, es: `Cada respuesta cita sus fuentes, cada acción ejecutada queda registrada.`, it: `Ogni risposta cita le proprie fonti, ogni azione eseguita viene registrata.`, nl: `Elk antwoord vermeldt zijn bronnen, elke uitgevoerde actie wordt gelogd.`, pt: `Cada resposta cita as suas fontes, cada ação executada é registada.` },
    'home.security.title': { en: `Your context stays yours.`, de: `Ihr Kontext bleibt Ihrer.`, es: `Su contexto sigue siendo suyo.`, it: `Il tuo contesto resta tuo.`, nl: `Uw context blijft van u.`, pt: `O seu contexto continua a ser seu.` },
    'legal.contact.h': { en: `Contact`, de: `Kontakt`, es: `Contacto`, it: `Contatto`, nl: `Contact`, pt: `Contacto` },
    'legal.contact.p1': { en: `For any question regarding this legal notice, write to <a href="mailto:support@leka-core.com">support@leka-core.com</a>.`, de: `Bei Fragen zu diesem Impressum schreiben Sie an <a href="mailto:support@leka-core.com">support@leka-core.com</a>.`, es: `Para cualquier pregunta sobre este aviso legal, escriba a <a href="mailto:support@leka-core.com">support@leka-core.com</a>.`, it: `Per qualsiasi domanda relativa alle presenti note legali, scrivi a <a href="mailto:support@leka-core.com">support@leka-core.com</a>.`, nl: `Voor vragen over deze juridische kennisgeving kunt u schrijven naar <a href="mailto:support@leka-core.com">support@leka-core.com</a>.`, pt: `Para qualquer questão relativa a este aviso legal, escreva para <a href="mailto:support@leka-core.com">support@leka-core.com</a>.` },
    'legal.droit.h': { en: `Governing law and jurisdiction`, de: `Anwendbares Recht und Gerichtsstand`, es: `Legislación aplicable y jurisdicción`, it: `Legge applicabile e giurisdizione`, nl: `Toepasselijk recht en bevoegde rechtbank`, pt: `Lei aplicável e jurisdição` },
    'legal.droit.p1': { en: `This legal notice is governed by English law. In the event of a dispute, and failing an amicable resolution, the courts of England and Wales shall have exclusive jurisdiction.`, de: `Dieses Impressum unterliegt englischem Recht. Im Streitfall und bei Ausbleiben einer gütlichen Einigung sind ausschließlich die Gerichte von England und Wales zuständig.`, es: `Este aviso legal se rige por la legislación inglesa. En caso de litigio, y a falta de resolución amistosa, los tribunales de Inglaterra y Gales tendrán competencia exclusiva.`, it: `Le presenti note legali sono disciplinate dal diritto inglese. In caso di controversia, e in mancanza di una risoluzione amichevole, i tribunali di Inghilterra e Galles avranno giurisdizione esclusiva.`, nl: `Deze juridische kennisgeving valt onder Engels recht. Bij een geschil, en bij gebrek aan een minnelijke schikking, zijn uitsluitend de rechtbanken van Engeland en Wales bevoegd.`, pt: `Este aviso legal rege-se pela lei inglesa. Em caso de litígio, e na falta de resolução amigável, os tribunais de Inglaterra e do País de Gales terão competência exclusiva.` },
